import{_ as t,o as a,c,a5 as o}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — Save Workspace Template (FR 3.4.17)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-17-save-workspace-template/plan.md","filePath":"feature/agency-workspace/3-4-17-save-workspace-template/plan.md"}'),n={name:"feature/agency-workspace/3-4-17-save-workspace-template/plan.md"};function d(r,e,i,l,s,p){return a(),c("div",null,[...e[0]||(e[0]=[o(`<h1 id="plan-—-save-workspace-template-fr-3-4-17" tabindex="-1">Plan — Save Workspace Template (FR 3.4.17) <a class="header-anchor" href="#plan-—-save-workspace-template-fr-3-4-17" aria-label="Permalink to &quot;Plan — Save Workspace Template (FR 3.4.17)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho user lưu cấu hình Workspace thành Template, resource độc lập <code>/api/v1/workspace-templates</code>. Không có thay đổi code trong lần đồng bộ này. ⚠ BA conflict: <code>WorkspaceTemplateServiceImpl</code> hiện tại mọi method (<code>saveTemplate</code>/<code>listTemplates</code>/<code>getTemplate</code>/<code>deleteTemplate</code>) đều <code>throw new UnsupportedOperationException(&quot;Not implemented yet&quot;)</code> — Controller/DTO/FE đã wired đúng contract dưới đây nhưng backend chưa thực sự chạy được. Mục 2-4 dưới đây mô tả <strong>contract dự kiến/đã thiết kế</strong>, không phải hành vi runtime thật hiện tại.</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>WorkspaceTemplateController</code>, <code>WorkspaceTemplateServiceImpl</code> (tên service suy theo pattern chung, xác nhận qua Grep controller)</td></tr><tr><td>File đã có</td><td><code>WorkspaceTemplate</code> entity, <code>WorkspaceTemplateResponse</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST   /api/v1/workspace-templates            { name, sourceWorkspaceId?, configSnapshot } → 200 WorkspaceTemplateResponse</span></span>
<span class="line"><span>GET    /api/v1/workspace-templates             → 200 [WorkspaceTemplateResponse]</span></span>
<span class="line"><span>GET    /api/v1/workspace-templates/{templateId} → 200 WorkspaceTemplateResponse</span></span>
<span class="line"><span>DELETE /api/v1/workspace-templates/{templateId} → 200 null</span></span></code></pre></div><p>Không lệch spec.md. Resource độc lập, KHÔNG nested dưới <code>/agencies/{id}</code> hay <code>/workspaces/{id}</code>.</p><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li><code>workspace_templates</code>: <code>id</code>, <code>agencyId</code> (tự set theo currentUser), <code>name</code>, <code>sourceWorkspaceId</code> (optional), <code>configSnapshot</code> (JSON string), <code>createdBy</code> (tự set), <code>createdAt</code>.</li><li><code>configSnapshot</code> độc lập với vòng đời Workspace gốc — Workspace gốc bị xóa không ảnh hưởng Template đã lưu.</li><li>Không migration (entity đã có).</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li>Create: validate <code>name</code>/<code>configSnapshot</code> không trống → 400 <code>VALIDATION_ERROR</code>; set <code>agencyId</code>/<code>createdBy</code> tự động theo currentUser; insert.</li><li>List: query theo <code>agencyId</code> của currentUser (hoặc phạm vi service quy định).</li><li>Detail: tìm theo <code>id</code> — không có → 404 <code>NOT_FOUND</code>.</li><li>Delete: tìm theo <code>id</code> — không có → 404 <code>NOT_FOUND</code>; xóa cứng record (không soft-delete).</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td>Không</td></tr><tr><td>Bị chặn</td><td><code>Create Workspace</code> (3.4.12) — chiều ngược, dùng Template để tạo Workspace mới là mở rộng UX, không bắt buộc trong CSV hiện tại</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Không có <code>@RequireRole</code> giới hạn cụ thể trên 4 endpoint</strong> — spec.md tự ghi nhận &quot;cần double-check với BE liệu có giới hạn quyền theo Agency/role dự kiến hay chưa&quot;. Rủi ro: bất kỳ user đã đăng nhập nào cũng gọi được list/detail template của Agency khác nếu không có filter theo <code>agencyId</code> đúng ở tầng service — cần xác nhận lại query List có filter đúng scope Agency của currentUser hay không.</li><li><strong>Detail/Delete dùng <code>404 NOT_FOUND</code> chung</strong> thay vì ErrorCode riêng cho template (khác pattern <code>WORKSPACE_NOT_FOUND</code>/<code>AGENCY_NOT_FOUND</code> các FR khác) — nên thống nhất naming nếu cần đồng bộ ErrorCode toàn hệ thống.</li><li><strong>Xóa cứng (không soft-delete)</strong> — khác pattern soft-delete phổ biến trong domain Workspace/Agency; chấp nhận vì Template không phải dữ liệu nghiệp vụ quan trọng cần khôi phục.</li></ul>`,15)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
